(function() {
    'use strict';

    class DEIAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Building an Inclusive Organization';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    briefing: 'Welcome to Novatek Solutions. As the new CPO you inherit a company with 12% women at VP+, a documented 8.4% gender pay gap, and belonging scores that vary dramatically by demographic group. The CEO expects measurable progress within 18 months. Your first quarter: establish your diagnostic baseline and initial strategic direction.',
                    briefingEs: 'Bienvenido a Novatek Solutions. Cómo nuevo CPO, hereda una empresa con 12% de mujeres en VP+, una brecha salarial de 8.4% y puntajes de pertenencia que difieren marcadamente por grupo. El CEO espera progreso medible en 18 meses. Primer trimestre: establezca su base de referencia.',
                    options: [
                        { value: 'external_audit', label: 'Commission External Pay Equity Audit', labelEs: 'Encargar Auditoría Externa de Equidad Salarial' },
                        { value: 'internal_audit', label: 'Conduct Internal Pay Analysis', labelEs: 'Realizar Análisis Salarial Interno' },
                        { value: 'no_audit', label: 'Delay Audit — Focus Elsewhere', labelEs: 'Postergar Auditoría — Enfocar Otros Temas' }
                    ],
                    event: null
                },
                {
                    briefing: 'Q2: Your initial investments are taking shape. HR reports that structured interview pilots have reduced demographic variance in hiring panels. The Women@Novatek ERG is requesting a strategic mandate upgrade. Meanwhile, a senior woman VP has departed for a competitor, citing lack of advancement.',
                    briefingEs: 'T2: Sus inversiones iniciales toman forma. RRHH reporta que las entrevistas estructuradas piloto redujeron varianza demográfica. El ERG Women@Novatek solicita un mandato estratégico mejorado. Una VP senior ha partido a un competidor, citando falta de avance.',
                    options: [
                        { value: 'structured_hiring', label: 'Implement Structured Behavioral Interviews', labelEs: 'Implementar Entrevistas Conductuales Estructuradas' },
                        { value: 'skills_assessment', label: 'Deploy Skills-Based Assessments', labelEs: 'Desplegar Evaluaciones Basadas en Habilidades' },
                        { value: 'diverse_panels', label: 'Mandate Diverse Interview Panels', labelEs: 'Requerir Paneles Diversos de Entrevista' }
                    ],
                    event: { text: 'A VP-level woman has exited Novatek for a competitor, citing lack of advancement. Her exit interview has spread internally. Employee sentiment is shaken.', textEs: 'Una VP mujer ha salido de Novatek hacia un competidor, citando falta de avance. Su entrevista de salida se ha difundido internamente. El clima laboral se ha debilitado.', belongingHit: -0.2, turnoverHit: 0.05 }
                },
                {
                    briefing: 'Q3: Mid-year review. Your pay equity data (if audited) reveals the full picture. The executive team is split: the Sales Director argues DEI investment diverts from revenue targets; the COO wants data before committing further. How will you structure your ERGs for maximum impact?',
                    briefingEs: 'T3: Revisión de medio período. Los datos de equidad salarial (si se auditaron) revelan el panorama completo. El equipo ejecutivo esta dividido: el Director de Ventas argumenta que la inversión DEI desvíe de metas de ingresos; el COO quiere datos antes de comprometerse. Cómo estructurara sus ERGs?',
                    options: [
                        { value: 'erg_social', label: 'ERGs as Social Affinity Groups', labelEs: 'ERGs como Grupos de Afinidad Social' },
                        { value: 'erg_talent', label: 'ERGs as Talent Development Accelerators', labelEs: 'ERGs como Aceleradores de Desarrollo de Talento' },
                        { value: 'erg_business', label: 'ERGs as Business Impact Advisors', labelEs: 'ERGs como Asesores de Impacto en Negocio' }
                    ],
                    event: null
                },
                {
                    briefing: 'Q4: End of Year 1. A pay equity document has leaked on an anonymous employee channel showing unadjusted gap data. Employees are demanding transparency. Your response this quarter will define organizational trust for the remaining mandate.',
                    briefingEs: 'T4: Fin del Primer Período. Un documento de equidad salarial se ha filtrado en un canal anónimo de empleados mostrando la brecha no ajustada. Los empleados exigen transparencia. Su respuesta este trimestre definirá la confianza organizacional.',
                    options: [
                        { value: 'full_transparency', label: 'Publish Full Pay Equity Report', labelEs: 'Publicar Informe Completo de Equidad Salarial' },
                        { value: 'internal_only', label: 'Share Aggregate Data Internally', labelEs: 'Compartir Datos Agregados Internamente' },
                        { value: 'suppress', label: 'Contain the Leak — Minimal Disclosure', labelEs: 'Contener la Filtración — Divulgacion Minima' }
                    ],
                    event: { text: 'PAY EQUITY LEAK: An internal document showing the unadjusted 23% gender pay gap has been shared on an anonymous employee channel. Social media mentions are growing. Employees demand a formal response.', textEs: 'FILTRACION DE EQUIDAD SALARIAL: Un documento interno mostrando la brecha salarial no ajustada del 23% se ha compartido en un canal anónimo. Las menciones en redes sociales crecen. Los empleados exigen una respuesta formal.', belongingHit: -0.3, turnoverHit: 0.08 }
                },
                {
                    briefing: 'Q5: Year 2 begins. A group of mid-level managers has circulated a document arguing DEI programs amount to reverse discrimination. The backlash is not hostile but it is organized. Your response will signal whether DEI at Novatek is a top-down mandate or a shared organizational commitment.',
                    briefingEs: 'T5: Comienza el período 2. Un grupo de gerentes de nivel medio ha circulado un documento argumentando que los programas DEI equivalen a discriminación inversa. La reaccion no es hostil pero esta organizada. Su respuesta señalará si DEI es un mandato o un compromiso compartido.',
                    options: [
                        { value: 'mandatory_training', label: 'Launch Mandatory Unconscious Bias Training', labelEs: 'Lanzar Capacitación Obligatoria de Sesgo Inconsciente' },
                        { value: 'voluntary_allyship', label: 'Deploy Voluntary Allyship Program', labelEs: 'Desplegar Programa Voluntario de Aliados' },
                        { value: 'inclusive_leadership', label: 'Embed Inclusion in Leadership Development', labelEs: 'Integrar Inclusión en Desarrollo de Liderazgo' }
                    ],
                    event: { text: 'DEI BACKLASH: A group of mid-level managers has circulated a document arguing that recent DEI initiatives constitute reverse discrimination and undermine meritocracy. The document has gained traction with 40+ managers.', textEs: 'REACCION ANTI-DEI: Un grupo de gerentes de nivel medio ha circulado un documento argumentando que las iniciativas DEI recientes constituyen discriminación inversa y socavan la meritocracia.', belongingHit: -0.15, turnoverHit: 0.03 }
                },
                {
                    briefing: 'Q6: A major ESG investor has requested a DEI disclosure aligned with GRI standards. Your existing data and reporting infrastructure will determine whether this becomes a credibility builder or a crisis. Colombia has also introduced mandatory pay equity reporting legislation.',
                    briefingEs: 'T6: Un inversor ESG importante ha solicitado una divulgacion DEI alineada con estandares GRI. Su infraestructura de datos determinara si esto fortalece o debilita su credibilidad. Colombia ha introducido legislación obligatoria de reporte de equidad salarial.',
                    options: [
                        { value: 'cdo_ceo', label: 'Appoint CDO Reporting to CEO', labelEs: 'Nombrar CDO Reportando al CEO' },
                        { value: 'cdo_hr', label: 'Appoint CDO Under HR', labelEs: 'Nombrar CDO bajo RRHH' },
                        { value: 'distributed', label: 'Embed DEI Accountability in Each Function', labelEs: 'Integrar Responsabilidad DEI en Cada Función' }
                    ],
                    event: { text: 'ESG PRESSURE: A major institutional investor requests formal DEI disclosure aligned with GRI/SASB standards. Additionally, Colombia introduces mandatory pay equity reporting for companies with 200+ employees.', textEs: 'PRESION ESG: Un inversor institucional importante solicita divulgacion DEI formal alineada con estandares GRI/SASB. Adicionalmente, Colombia introduce reporte obligatorio de equidad salarial.', belongingHit: 0, turnoverHit: 0 }
                },
                {
                    briefing: 'Q7: Your programs are maturing. The data now shows clear patterns: structural interventions are producing measurable change while awareness-only programs show sentiment improvement without structural movement. How will you set goals for the final stretch?',
                    briefingEs: 'T7: Sus programas están madurando. Los datos muestran patrones claros: las intervenciones estructurales producen cambio medible mientras que los programas solo de sensibilización muestran mejora de sentimiento sin cambio estructural. Cómo establecerá metas para el tramo final?',
                    options: [
                        { value: 'timebound_targets', label: 'Set Specific Time-Bound Representation Targets', labelEs: 'Establecer Metas de Representación con Plazo Definido' },
                        { value: 'progress_goals', label: 'Set Progress-Based Improvement Goals', labelEs: 'Establecer Metas de Mejora Basadas en Progreso' },
                        { value: 'aspirational', label: 'Set Aspirational Goals Without Timelines', labelEs: 'Establecer Metas Aspiracionales Sin Plazos' }
                    ],
                    event: null
                },
                {
                    briefing: 'Q8: Final quarter before the board review. The CEO needs to present a credible narrative of progress. Your metrics, your governance structures, and your evidence of lasting cultural change will determine whether this is viewed as a successful transformation or a communications exercise.',
                    briefingEs: 'T8: Último trimestre antes de la revisión de junta. El CEO necesita presentar una narrativa creible de progreso. Sus métricas, estructuras de gobierno y evidencia de cambio cultural duradero determinarán si esto se ve como una transformacion exitosa o un ejercicio de comunicación.',
                    options: [
                        { value: 'public_report', label: 'Publish External DEI Annual Report', labelEs: 'Publicar Informe Anual DEI Externo' },
                        { value: 'internal_report', label: 'Present Internal Progress Dashboard', labelEs: 'Presentar Tablero de Progreso Interno' },
                        { value: 'bonus_tied', label: 'Tie Executive Bonuses to DEI Metrics', labelEs: 'Vincular Bonos Ejecutivos a Métricas DEI' }
                    ],
                    event: null
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    womenVP: 12,
                    minorityVP: 2,
                    genderPayGap: 8.4,
                    racialPayGap: 6.1,
                    belongingScore: 6.4,
                    belongingGap: 2.7,
                    turnoverUR: 1.5,
                    execAlignment: 3.0,
                    totalSpent: 0,
                    auditDone: false,
                    auditQuality: 0,
                    ergModel: 'social',
                    representationHistory: [],
                    payGapHistory: [],
                    belongingHistory: [],
                    execAlignHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    hiringInvest: 50,
                    payEquityInvest: 50,
                    inclusionInvest: 50,
                    ergInvest: 25,
                    accountInvest: 25,
                    strategy: 'external_audit'
                };
            }
            this._setupSliderListeners();
            this._updateBriefing(state);
        }

        _setupSliderListeners() {
            var sliders = ['hiringInput', 'payEquityInput', 'inclusionInput', 'ergInput', 'accountInput'];
            var valueIds = ['hiringValue', 'payEquityValue', 'inclusionValue', 'ergValue', 'accountValue'];
            var self = this;

            sliders.forEach(function(sliderId, i) {
                var slider = document.getElementById(sliderId);
                if (slider) {
                    slider.addEventListener('input', function() {
                        var valEl = document.getElementById(valueIds[i]);
                        if (valEl) valEl.textContent = slider.value;
                        self._updateBudgetTotal();
                    });
                }
            });
        }

        _updateBudgetTotal() {
            var h = parseInt(document.getElementById('hiringInput')?.value || 0);
            var p = parseInt(document.getElementById('payEquityInput')?.value || 0);
            var inc = parseInt(document.getElementById('inclusionInput')?.value || 0);
            var e = parseInt(document.getElementById('ergInput')?.value || 0);
            var a = parseInt(document.getElementById('accountInput')?.value || 0);
            var total = h + p + inc + e + a;
            var el = document.getElementById('totalAllocated');
            if (el) {
                el.textContent = '$' + total + 'K';
                el.style.color = total > 250 ? '#e74c3c' : '#27ae60';
            }
            var remEl = document.getElementById('budgetRemainingDisplay');
            if (remEl) {
                var rem = Math.max(0, 250 - total);
                remEl.textContent = '$' + rem + 'K';
                remEl.style.color = total > 250 ? '#e74c3c' : '#27ae60';
            }
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var lang = (window.mySimulation && window.mySimulation.currentLanguage) || 'en';

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                briefEl.innerHTML = lang === 'es' ? round.briefingEs : round.briefing;
            }

            var selectEl = document.getElementById('strategySelect');
            if (selectEl) {
                selectEl.innerHTML = '';
                round.options.forEach(function(opt) {
                    var option = document.createElement('option');
                    option.value = opt.value;
                    option.textContent = lang === 'es' ? opt.labelEs : opt.label;
                    selectEl.appendChild(option);
                });
            }

            var eventPanel = document.getElementById('eventPanel');
            var eventText = document.getElementById('eventText');
            if (eventPanel && eventText) {
                if (round.event) {
                    eventPanel.style.display = 'block';
                    eventText.innerHTML = lang === 'es' ? round.event.textEs : round.event.text;
                } else {
                    eventPanel.style.display = 'none';
                }
            }
        }

        validateDecisions(decisions) {
            var hEl = document.getElementById('hiringInput');
            var pEl = document.getElementById('payEquityInput');
            var iEl = document.getElementById('inclusionInput');
            var eEl = document.getElementById('ergInput');
            var aEl = document.getElementById('accountInput');
            var sEl = document.getElementById('strategySelect');

            if (hEl) decisions.hiringInvest = parseInt(hEl.value);
            if (pEl) decisions.payEquityInvest = parseInt(pEl.value);
            if (iEl) decisions.inclusionInvest = parseInt(iEl.value);
            if (eEl) decisions.ergInvest = parseInt(eEl.value);
            if (aEl) decisions.accountInvest = parseInt(aEl.value);
            if (sEl) decisions.strategy = sEl.value;

            var total = decisions.hiringInvest + decisions.payEquityInvest + decisions.inclusionInvest + decisions.ergInvest + decisions.accountInvest;

            if (total > 250) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_warning'), 'warning'
                );
                return false;
            }
            if (total <= 0) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('zero_warning'), 'warning'
                );
                return false;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];
            var totalSpent = d.hiringInvest + d.payEquityInvest + d.inclusionInvest + d.ergInvest + d.accountInvest;

            var accountMultiplier = 1 + (d.accountInvest / 50) * 0.35;

            if (d.accountInvest >= 30) {
                ds.execAlignment = Math.min(10, ds.execAlignment + 0.45 * accountMultiplier);
            } else if (d.accountInvest >= 15) {
                ds.execAlignment = Math.min(10, ds.execAlignment + 0.2);
            } else {
                ds.execAlignment = Math.max(1, ds.execAlignment - 0.1);
            }

            var strategyBonus = this._applyStrategy(d.strategy, ds, state.currentPeriod);

            var hiringEffect = (d.hiringInvest / 100) * 1.1 * accountMultiplier;
            ds.womenVP = Math.min(50, ds.womenVP + hiringEffect * 0.65 + strategyBonus.repBonus);
            ds.minorityVP = Math.min(30, ds.minorityVP + hiringEffect * 0.3 + strategyBonus.repBonus * 0.4);

            var payAuditMult = ds.auditDone ? (1 + ds.auditQuality * 0.3) : 0.4;
            var payEffect = (d.payEquityInvest / 100) * 0.9 * accountMultiplier * payAuditMult;
            ds.genderPayGap = Math.max(0, ds.genderPayGap - payEffect + strategyBonus.payBonus);
            ds.racialPayGap = Math.max(0, ds.racialPayGap - payEffect * 0.75);

            var belongInclusion = (d.inclusionInvest / 100) * 0.32;
            var belongStructural = ((d.hiringInvest + d.payEquityInvest) / 200) * 0.15 * accountMultiplier;
            var belongERG = (d.ergInvest / 50) * 0.12;
            ds.belongingScore = Math.min(10, ds.belongingScore + belongInclusion + belongStructural + belongERG + strategyBonus.belongBonus);

            var gapReduction = (belongStructural * 0.25 + belongERG * 0.12) * accountMultiplier;
            ds.belongingGap = Math.max(0, ds.belongingGap - gapReduction + strategyBonus.gapBonus);

            var turnoverReduction = ((d.payEquityInvest + d.hiringInvest) / 200) * 0.06 * accountMultiplier;
            turnoverReduction += belongERG * 0.025;
            ds.turnoverUR = Math.max(1.0, ds.turnoverUR - turnoverReduction);

            if (totalSpent > 0 && (d.inclusionInvest / totalSpent) > 0.55 && d.accountInvest < 15) {
                ds.belongingScore = Math.max(4, ds.belongingScore - 0.1);
                ds.execAlignment = Math.max(1, ds.execAlignment - 0.15);
            }

            if (round.event) {
                ds.belongingScore = Math.max(3, ds.belongingScore + (round.event.belongingHit || 0));
                ds.turnoverUR = Math.min(2.5, ds.turnoverUR + (round.event.turnoverHit || 0));
            }

            ds.totalSpent += totalSpent;

            ds.representationHistory.push(Math.round(ds.womenVP * 10) / 10);
            ds.payGapHistory.push(Math.round(ds.genderPayGap * 10) / 10);
            ds.belongingHistory.push(Math.round(ds.belongingScore * 10) / 10);
            ds.execAlignHistory.push(Math.round(ds.execAlignment * 10) / 10);

            var results = {
                period: state.currentPeriod,
                totalSpent: totalSpent,
                womenVP: Math.round(ds.womenVP * 10) / 10,
                minorityVP: Math.round(ds.minorityVP * 10) / 10,
                genderPayGap: Math.round(ds.genderPayGap * 10) / 10,
                racialPayGap: Math.round(ds.racialPayGap * 10) / 10,
                belongingScore: Math.round(ds.belongingScore * 10) / 10,
                belongingGap: Math.round(ds.belongingGap * 10) / 10,
                turnoverUR: Math.round(ds.turnoverUR * 100) / 100,
                execAlignment: Math.round(ds.execAlignment * 10) / 10
            };

            var nextPeriod = (state.currentPeriod || 1) + 1;
            if (nextPeriod <= (state.maxPeriods || this.ROUNDS.length)) {
                this._updateBriefing({ currentPeriod: nextPeriod });
            }

            return results;
        }

        _applyStrategy(strategy, ds, period) {
            var bonus = { repBonus: 0, payBonus: 0, belongBonus: 0, gapBonus: 0 };

            switch (strategy) {
                case 'external_audit':
                    ds.auditDone = true;
                    ds.auditQuality = 1.0;
                    bonus.payBonus = -0.3;
                    break;
                case 'internal_audit':
                    ds.auditDone = true;
                    ds.auditQuality = 0.5;
                    bonus.payBonus = -0.15;
                    break;
                case 'no_audit':
                    break;
                case 'structured_hiring':
                    bonus.repBonus = 0.6;
                    break;
                case 'skills_assessment':
                    bonus.repBonus = 0.8;
                    break;
                case 'diverse_panels':
                    bonus.repBonus = 0.4;
