        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};

            var womenVP = r.womenVP || 12;
            var payGap = r.genderPayGap || 8.4;
            var belonging = r.belongingScore || 6.4;
            var turnover = r.turnoverUR || 1.5;
            var execAlign = r.execAlignment || 3;

            var score = 0;
            if (womenVP >= 25) score += 25; else if (womenVP >= 18) score += 15; else score += 5;
            if (payGap <= 2) score += 25; else if (payGap <= 5) score += 15; else score += 5;
            if (belonging >= 8) score += 20; else if (belonging >= 7) score += 12; else score += 4;
            if (turnover <= 1.1) score += 15; else if (turnover <= 1.25) score += 10; else score += 3;
            if (execAlign >= 7) score += 15; else if (execAlign >= 5) score += 8; else score += 2;

            var performance = 'Needs Improvement';
            if (score >= 80) performance = 'Transformational Leader';
            else if (score >= 60) performance = 'Strong Progress';
            else if (score >= 40) performance = 'Moderate Progress';

            var totalSpent = history.reduce(function(s, h) { return s + (h.results?.totalSpent || 0); }, 0);

            var insights = [];
            if (payGap <= 2) insights.push('Pay equity gap virtually eliminated — strong structural intervention.');
            if (payGap > 5) insights.push('Pay gap remains significant. Pay audits with full remediation are the most direct lever.');
            if (womenVP >= 25) insights.push('Representation at VP+ has improved substantially through structural hiring changes.');
            if (womenVP < 18) insights.push('Representation improvement was limited. Structured hiring and accountability drive the strongest gains.');
            if (belonging >= 8 && payGap > 5) insights.push('High belonging scores without pay equity change suggests sentiment improvement without structural change — the classic DEI trap.');
            if (execAlign >= 7) insights.push('Strong executive alignment indicates accountability structures are working.');
            if (execAlign < 5) insights.push('Low executive alignment suggests DEI remains a communications exercise rather than a strategic priority.');

            return {
                totalBudgetUsed: '$' + totalSpent + 'K',
                finalWomenVP: womenVP + '%',
                finalPayGap: payGap + '%',
                finalBelonging: belonging + '/10',
                finalTurnover: turnover + 'x',
                finalExecAlignment: execAlign + '/10',
                overallScore: score,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;

            if (results.genderPayGap > 6 && state.currentPeriod >= 3) {
                return window.mySimulation.t('hint_pay_gap');
            }
            if (results.belongingScore > 7.5 && results.womenVP < 15) {
                return window.mySimulation.t('hint_sentiment_trap');
            }
            if (results.execAlignment < 4 && state.currentPeriod >= 4) {
                return window.mySimulation.t('hint_exec_alignment');
            }
            if (results.turnoverUR > 1.4 && state.currentPeriod >= 5) {
                return window.mySimulation.t('hint_turnover');
            }
            if (state.currentPeriod <= 2 && !state.domainState.auditDone) {
                return window.mySimulation.t('hint_audit');
            }
            return null;
        }

